CREATE OR REPLACE FUNCTION control.resolve_authenticated_operator_gate(p_actor uuid, p_run uuid, p_gate text, p_response text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'control'
AS $function$
DECLARE item jsonb; ev control.operator_authority_events%ROWTYPE; g control.sas_final_gate_review_grants%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.operator_actors WHERE actor_id=p_actor AND enabled) THEN RAISE EXCEPTION 'registered_authenticated_operator_required';END IF;
 IF p_response NOT IN('approve','reject','revoke') THEN RAISE EXCEPTION 'typed_operator_response_required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('operator-gate:'||p_run::text,0));
 PERFORM 1 FROM control.workflow_runs WHERE run_id=p_run FOR UPDATE;
 SELECT * INTO ev FROM control.operator_authority_events WHERE run_id=p_run AND gate_fingerprint=p_gate AND response=p_response;
 IF FOUND AND ev.action='sas-final-gate-single-review' THEN RETURN to_jsonb(ev)||jsonb_build_object('ok',true,'replayed',true,'resolution_id',ev.event_id);END IF;
 IF p_response='revoke' THEN SELECT offer INTO item FROM control.operator_authority_events WHERE run_id=p_run AND gate_fingerprint=p_gate AND response='approve';
 ELSE SELECT value INTO item FROM jsonb_array_elements(control.operator_gate_offers(p_run)) WHERE value->>'gate_fingerprint'=p_gate;END IF;
 IF item->>'action' IS DISTINCT FROM 'sas-final-gate-single-review' THEN RETURN control.resolve_authenticated_operator_gate_before_sas_single_review(p_actor,p_run,p_gate,p_response);END IF;
 PERFORM 1 FROM control.tasks WHERE task_id='SAS-M1-GATE-001' FOR UPDATE;
 IF p_response='revoke' THEN
 SELECT * INTO g FROM control.sas_final_gate_review_grants WHERE run_id=p_run AND event_id=(SELECT event_id FROM control.operator_authority_events WHERE run_id=p_run AND gate_fingerprint=p_gate AND response='approve') FOR UPDATE;
 IF g.grant_id IS NULL OR g.revoked_at IS NOT NULL OR g.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'unconsumed_review_authority_required';END IF;
 ELSE
 IF EXISTS(SELECT 1 FROM control.operator_authority_events WHERE run_id=p_run AND gate_fingerprint=p_gate)
 OR control.sas_final_gate_single_review_offer(p_run)->>'gate_fingerprint' IS DISTINCT FROM p_gate THEN RAISE EXCEPTION 'single_review_offer_stale_or_decided';END IF;
 END IF;
 INSERT INTO control.operator_authority_events(run_id,task_id,gate_fingerprint,action,response,actor_id,offer)
 VALUES(p_run,'SAS-M1-GATE-001',p_gate,'sas-final-gate-single-review',p_response,p_actor,item) RETURNING * INTO ev;
 IF p_response='approve' THEN
 INSERT INTO control.sas_final_gate_review_grants(event_id,run_id,task_id,identity_fingerprint,actor_id,model_profile,model_name,reasoning_effort)
 VALUES(ev.event_id,p_run,'SAS-M1-GATE-001',item->>'identity_fingerprint',p_actor,'review',item->>'model_name',item->>'reasoning_effort');
 -- Resolve only this installed hold. Native queue acquisition restores its prior
 -- claimed state; the operator never writes task status or attempts.
 UPDATE control.recovery_states SET status='resolved',resolved_at=now(),updated_at=now(),version=version+1
 WHERE current_task_id='SAS-M1-GATE-001' AND status='active' AND error_code='sas_final_gate_current_chat_review_required';
 ELSIF p_response='revoke' THEN UPDATE control.sas_final_gate_review_grants SET revoked_at=now() WHERE grant_id=g.grant_id;END IF;
 INSERT INTO control.audit_events(project_id,workstream_slug,task_id,action,source,new_value,metadata)
 VALUES('f71b3b2b-d56b-4f7e-94f5-0b8c379a1088','super-admin-suit','SAS-M1-GATE-001','sas_single_review_'||p_response,'human',to_jsonb(ev),jsonb_build_object('max_new_executions',1,'documentation_event_preserved',27));
 INSERT INTO control.task_events(task_id,event_type,source,payload) VALUES('SAS-M1-GATE-001','sas_single_review_'||p_response,'human',to_jsonb(ev));
 IF p_response IN('approve','revoke') THEN PERFORM control.enqueue_supervisor_wake(p_run);END IF;
 RETURN to_jsonb(ev)||jsonb_build_object('ok',true,'resolution_id',ev.event_id);
END $function$
